"""
test_basisTensor.py
Test basisTensor class, output all vectors
"""

import math
import torch
from basisHD import basisTensor, _baseTensorDictIns


def test_all_vectors():
    """Output all vectors generated by basisTensor.random"""
    
    # ========== Configuration ==========
    dimensions = 8          # must be a power of 2
    num_vectors = 8         # must be <= dimensions
    dtype = torch.float32
    device = torch.device("cpu")
    # ===================================
    
    print("=" * 70)
    print("Test 1: Generate all vectors via basisTensor.random")
    print("=" * 70)
    print(f"dimensions = {dimensions}")
    print(f"num_vectors = {num_vectors}")
    print(f"dtype = {dtype}")
    print(f"device = {device}")
    print()
    
    # Generate vectors
    vectors = basisTensor.random(
        num_vectors=num_vectors,
        dimensions=dimensions,
        dtype=dtype,
        device=device,
    )
    
    print(f"Return type: {type(vectors)}")
    print(f"Vector shape: {vectors.shape}")
    print()
    print("All vectors:")
    for i in range(num_vectors):
        print(f"  vec[{i}] = {vectors[i].tolist()}")
    print()
    
    # Check pairwise orthogonality (inner product)
    print("-" * 70)
    print("Pairwise inner products (should be ~0, indicating orthogonality):")
    print("-" * 70)
    for i in range(num_vectors):
        row = []
        for j in range(num_vectors):
            dot = torch.dot(vectors[i].float(), vectors[j].float()).item()
            row.append(f"{dot:8.3f}")
        print(f"  vec[{i}]: " + " ".join(row))
    print()
    
    return vectors


def test_tensor_dict_ins():
    """Test _baseTensorDictIns index allocation, output all index combinations"""
    
    print("=" * 70)
    print("Test 2: _baseTensorDictIns all index combinations")
    print("=" * 70)
    
    dimensions = 8
    ins = _baseTensorDictIns(dimensions, name="demo", RecordCreateHistory=True)
    
    print(f"dimensions = {dimensions}")
    print(f"CountMax   = {ins.CountMax}")
    print(f"Expected   = {dimensions}")
    print()
    
    print("All index combinations (print internal list before popping):")
    ins._print_AllTensorList()
    print()
    
    # Pop all one by one
    print("Pop all via popTensor:")
    for i in range(ins.CountMax):
        idx = ins.popTensor()
        print(f"  pop[{i}] -> {idx}")
    
    print()
    print("Try popping once more (should raise BufferError):")
    try:
        ins.popTensor()
    except BufferError as e:
        print(f"  Correctly caught exception: {e}")
    print()
    
    return ins


def test_group_index():
    """Test groupIndex2Tensor: generate vectors from seedTensor using index combinations"""
    
    print("=" * 70)
    print("Test 3: groupIndex2Tensor generates all vectors from index combinations")
    print("=" * 70)
    
    import seedgen
    
    dimensions = 8
    dtype = torch.float32
    device = torch.device("cpu")
    
    # Generate seedTensor
    seedTensor = seedgen.seedgen_all(dimensions, polar=0, dtype=dtype, device=device)
    print(f"seedTensor shape: {seedTensor[0][0].shape if hasattr(seedTensor[0][0], 'shape') else 'N/A'}")
    print()
    
    # Get all indices
    ins = _baseTensorDictIns(dimensions, name="demo")
    all_indices = []
    for _ in range(ins.CountMax):
        all_indices.append(ins.popTensor())
    
    print("All index combinations and corresponding bipolar vectors:")
    for k, idx in enumerate(all_indices):
        vec = basisTensor.groupIndex2Tensor(
            seedTensor, idx, dtype=dtype, device=device, dform="bipolar"
        )
        vec_flat = vec.flatten().tolist()
        # FIX: use str(idx) instead of {idx:20s} since idx is a list, not a string
        print(f"  index={str(idx):20s} -> {vec_flat}")
    print()
    
    print("All index combinations and corresponding binary vectors:")
    for k, idx in enumerate(all_indices):
        vec = basisTensor.groupIndex2Tensor(
            seedTensor, idx, dtype=dtype, device=device, dform="binary"
        )
        vec_flat = vec.flatten().tolist()
        # FIX: convert list to string before formatting
        print(f"  index={str(idx):20s} -> {vec_flat}")
    print()
    
    return all_indices


if __name__ == "__main__":
    print("\n")
    print("#" * 70)
    print("# basisTensor Test Demo")
    print("#" * 70)
    print("\n")
    
    # Test 1: basisTensor.random
    vectors = test_all_vectors()
    
    # Test 2: index dictionary
    ins = test_tensor_dict_ins()
    
    # Test 3: groupIndex2Tensor
    all_indices = test_group_index()
    
    print("#" * 70)
    print("# All tests completed")
    print("#" * 70)